---@type SVfAppActivityPkSender
local SVfAppActivityPkSender = T(Global, "PidPacketSender")

---@class SVfAppActivity
local SVfAppActivity = {}

---@param player SBasePlayer
function SVfAppActivity:addGameBadge(player)
    WebService.AddGameBadge(player.userId, player:getLanguage(), function(data)
        if not player:checkReady() then
            return
        end
        SVfAppActivityPkSender:sendGetGameBadgeSuccess(player, data)
    end)
end

---@param player SBasePlayer
function SVfAppActivity:removeGameBadge(player)
    WebService.RemoveGameBadge(player.userId)
end

return SVfAppActivity